contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        address baseToken = address(0);
        address nft = address(1);
        uint128 virtualBase = 100 ether;
        uint128 virtualNft = 10 ether;
        uint56 changeFee = 0;
        uint16 feeRate = 0;
        bytes32 merkleRoot = bytes32(0);
        bool useStolen = false;
        bool payRoyalties = false;
        c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties);

        bool ok;
        try c.availableForFlashLoan(nft, 1) {
            ok = true;
        } catch {
            ok = false;
